@RetryableTopic(
        attempts = "4",
        backoff = @Backoff(delay = 2_000, multiplier = 3.0),   // 2s, 6s, 18s
        dltTopicSuffix = ".DLT",
        autoCreateTopics = "true",
        exclude = { JsonProcessingException.class })
@KafkaListener(topics = "orders", groupId = "inventory")
public void on(OrderEvent e) {
    inventory.reserve(e);
}

@DltHandler
public void dead(OrderEvent e,
                 @Header(KafkaHeaders.ORIGINAL_TOPIC) String topic,
                 @Header(KafkaHeaders.ORIGINAL_OFFSET) long offset,
                 @Header(KafkaHeaders.EXCEPTION_MESSAGE) String message) {
    alerting.notify("처리 실패 %s@%d %s".formatted(topic, offset, message));
}
